use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let data = input.as_array();
    if data.is_none() {
        return serde_json::Value::Null;
    }

    let mut finish_times = Vec::new();
    let mut current_finish = 0;

    for item in data {
        let arrival = item.as_i64().unwrap();
        let duration = item.as_i64().unwrap();

        current_finish = std::cmp::max(current_finish, arrival + duration);
        finish_times.push(current_finish);
    }

    serde_json::Value::Array(finish_times)
}

fn main() {
    let input = serde_json::Value::from("{\"input\":[[0,3],[1,2],[8,1]],\"expected\":[3,5,9]}");
    let result = solve(input);
    println!("{:?}", result);
}
```

